// Annonceurs fictifs créés par les anciens seeds (supprimés au prochain seed).
const OLD_DEMO_PARTNERS = ['Annonceurs de démonstration', 'Akwaba Money', 'Ananas d’Agou', 'Wax d’Assigamé', 'Lomé Tech Academy', 'Riz du Mono', 'Sécurité routière (démo)'];

async function main(): Promise<void> {
  for (const code of SYSTEM_WALLETS) {
    await prisma.wallet.upsert({ where: { systemCode: code }, create: { systemCode: code }, update: {} });
  }
  // L'horloge du jeu démarre au premier seed (jour 0) ; modifiable ensuite dans le back-office.
  await prisma.gameSetting.upsert({
    where: { key: 'game.clock' },
    create: { key: 'game.clock', value: { epochRealMs: Date.now(), secondsPerGameDay: 3600 } },
    update: {},
  });
  for (const j of JOBS) await prisma.job.upsert({ where: { id: j.id }, create: j, update: j });
  for (const f of FOODS) await prisma.foodItem.upsert({ where: { id: f.id }, create: f, update: f });
  for (const p of PRODUCTS) await prisma.product.upsert({ where: { id: p.id }, create: p, update: { nameFr: p.nameFr, nameEn: p.nameEn } });
  for (const v of VENUES) await prisma.venue.upsert({ where: { id: v.id }, create: v, update: v });
  // Lieux retirés de la liste (anciennes versions) : désactivés, pour ne plus s'afficher par-dessus les autres
  // (les lieux « brand_… » des partenaires sont gérés par le serveur, pas par cette liste)
  await prisma.venue.updateMany({ where: { id: { notIn: VENUES.map((v) => v.id) }, NOT: { id: { startsWith: 'brand_' } } }, data: { enabled: false } });
  for (const [i, a] of ACTIVITIES.entries()) {
    const data = { ...a, sort: i };
    await prisma.venueActivity.upsert({ where: { id: a.id }, create: data, update: data });
  }
  // Activités retirées de la liste (ex. « Consultation » des hôpitaux, remplacée par le dossier médical de l'appli Santé) : désactivées
  await prisma.venueActivity.updateMany({ where: { id: { notIn: ACTIVITIES.map((a) => a.id) }, NOT: { id: { startsWith: 'brand_' } } }, data: { enabled: false } });
  // Aucune publicité au lancement : les espaces sont vendus aux annonceurs.
  // Les annonceurs fictifs créés par les anciens seeds sont retirés (jamais une annonce payée ni un partenaire lié à un compte).
  const oldDemo = { name: { in: OLD_DEMO_PARTNERS }, accountId: null, campaigns: { none: { purchaseId: { not: null } } } };
  const oldCampaigns = await prisma.campaign.findMany({ where: { partner: oldDemo }, select: { id: true } });
  // campaign_image n'a pas de clé étrangère : ses lignes sont retirées à la main
  await prisma.campaignImage.deleteMany({ where: { campaignId: { in: oldCampaigns.map((c) => c.id) } } });
  await prisma.partner.deleteMany({ where: oldDemo });
  // eslint-disable-next-line no-console
  console.log(`seed ok: ${SYSTEM_WALLETS.length} system wallets, ${JOBS.length} jobs, ${FOODS.length} foods, ${PRODUCTS.length} products, ${VENUES.length} venues, ${ACTIVITIES.length} activities`);
}

main()
  .catch((e) => {
    // eslint-disable-next-line no-console
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
